svg.script:
function svgRoot(){return document.documentElement;}
function playPause(){var s=svgRoot();if(s.animationsPaused())s.unpauseAnimations();else s.pauseAnimations();}
function scrub(v){var s=svgRoot();s.pauseAnimations();s.setCurrentTime(parseFloat(v));var l=document.getElementById('tlabel');if(l)l.textContent='t = '+parseFloat(v).toFixed(1)+' s';}
